"""Return objects describing generated report artefacts."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class ComparisonReportResult:
    """Paths generated by an experiment comparison report."""

    report_path: Path
    output_dir: Path
    runs_index_csv_path: Path
    diagnostics_csv_path: Path
    pairwise_ks_csv_path: Path
    benchmark_diagnostics_csv_path: Path | None = None
    simulation_vs_benchmark_csv_path: Path | None = None
    seed_robustness_csv_path: Path | None = None
    stress_regime_csv_path: Path | None = None
    figure_index_csv_path: Path | None = None
    agent_summary_csv_path: Path | None = None

@dataclass(frozen=True)
class SeedRobustnessReportResult:
    """Paths generated by a dedicated seed-robustness report."""

    report_path: Path
    output_dir: Path
    runs_index_csv_path: Path
    diagnostics_csv_path: Path
    pairwise_ks_csv_path: Path
    seed_robustness_csv_path: Path
    distribution_tests_csv_path: Path
    adf_stationarity_csv_path: Path
    seed_convergence_csv_path: Path
    verdicts_csv_path: Path
    figure_index_csv_path: Path


@dataclass(frozen=True)
class RunReportResult:
    """Paths generated by a single-run analysis report."""

    report_path: Path
    output_dir: Path
    diagnostics_csv_path: Path
    returns_csv_path: Path
    benchmark_diagnostics_csv_path: Path | None = None
    simulation_vs_benchmark_csv_path: Path | None = None
    seed_robustness_csv_path: Path | None = None
    stress_regime_csv_path: Path | None = None
    figure_index_csv_path: Path | None = None
    agent_summary_csv_path: Path | None = None
